function pick(e){const r=canvas.getBoundingClientRect();let best=null,d=26;for(let u of battle.units){if(u.hp<=0||editing&&!editor.rules.canEditTeam(u.team))continue;let q=camera.project(u.x,u.y+1.3,u.z,r.width,r.height);if(q){let dd=Math.hypot(q[0]-(e.clientX-r.left),q[1]-(e.clientY-r.top));if(dd<d){best={kind:'unit',id:u.id};d=dd;}}}if(editing&&!isChallenge()){let p=groundAt(e);for(const o of editor.stage.terrain){let def=terrainData[o.type],radius=(def.radius||def.width/2)*(o.scale||1);let q=camera.project(o.x,battle.terrain.heightAt(o.x,o.z)+(def.blocking?def.height*(o.scale||1)/2:0),o.z,r.width,r.height),dd=q?Math.hypot(q[0]-(e.clientX-r.left),q[1]-(e.clientY-r.top)):Infinity;if(dd<d||(p&&Math.hypot(p.x-o.x,p.z-o.z)<radius&&!best)){best={kind:'terrain',id:o.id};d=Math.min(d,dd);}}}return best;}
