const legacyPointerDown=canvas.onpointerdown,legacyPointerMove=canvas.onpointermove,legacyPointerUp=canvas.onpointerup,legacyPointerCancel=canvas.onpointercancel;
canvas.onpointerdown=e=>{legacyPointerDown(e);if(pointers.size>1){if(selectionGesture||[...pointers.values()].some(p=>p.editIntercept)){cancelSelectionGesture();for(const p of pointers.values())p.suppressEdit=true;}return;}
 if(editing&&e.button===0&&['select','move'].includes($('editTool').value)&&($('editTool').value==='select'||unitSelection.ids.size)){marker=null;beginSelectionGesture(e,pointers.get(e.pointerId));}
};
canvas.onpointermove=e=>{const p=pointers.get(e.pointerId);if(p&&pointers.size===1&&(p.editIntercept||p.suppressEdit)){p.x=e.clientX;p.y=e.clientY;p.moved=p.moved||Math.hypot(p.x-p.startX,p.y-p.startY)>6;if(p.mode!==inputMode())cancelSelectionGesture();if(selectionGesture&&!p.suppressEdit)updateSelectionGesture(e);gesture=state();return;}legacyPointerMove(e);};
canvas.onpointerup=e=>{const p=pointers.get(e.pointerId);if(p&&(p.editIntercept||p.suppressEdit)){if(!p.suppressEdit&&pointers.size===1&&selectionGesture?.pointer===e.pointerId)finishSelectionGesture(e);else cancelSelectionGesture();pointers.delete(e.pointerId);gesture=state();return;}legacyPointerUp(e);};
canvas.onpointercancel=e=>{cancelSelectionGesture();for(const p of pointers.values())p.suppressEdit=true;legacyPointerCancel(e);};
canvas.addEventListener('lostpointercapture',e=>{if(pointers.has(e.pointerId)){brushSession=null;cancelSelectionGesture();for(const p of pointers.values())p.suppressEdit=true;pointers.delete(e.pointerId);gesture=state();}});
window.addEventListener('blur',()=>{cancelSelectionGesture();pointers.clear();gesture=null;brushSession=null;});
canvas.addEventListener('wheel',()=>cancelSelectionGesture(),{passive:true});
window.addEventListener('keydown',e=>{if(!editing||e.key!=='Escape'||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;cancelSelectionGesture();unitSelection.clear();editSelected=null;refreshEditor();});
function ui(){updateDefenseUI();updateCameraStatus();if(editing)updateSelectionUI();if(!editing)updateGodUI();if(editing){if(!editSelected&&['place','brush'].includes($('editTool').value))$('selected').textContent=$('editTool').value==='brush'?`${teamLabel(Number($('placeTeam').value))} / ${characterData[Number($('placeType').value)].name} ${$('brushCount').value}体ずつ — なぞって配置`:placementDescription()+' — 戦場をタップ';for(let t=0;t<4;t++){$('hp'+t).value=battle.initial[t]?1:0;$('stats'+t).textContent=`${battle.alive[t]} 体配置`;}return;}for(let t=0;t<4;t++){$('hp'+t).value=Math.max(0,battle.initial[t]?battle.hp[t]/battle.initial[t]:0);$('stats'+t).textContent=`${battle.alive[t].toLocaleString()} 人 / HP ${Math.ceil(battle.hp[t]).toLocaleString()}`;}let s=Math.floor(battle.time);$('clock').textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;if(godActive)$('selected').textContent=godAbility==='reinforcement'?placementDescription()+' — ここに配置：戦場をタップ':godAbilities[godAbility].name+' / '+(godAbility==='heal'?$('healTarget').selectedOptions[0].textContent:'全TEAM')+' — 地面をタップ';else if(selected?.data)$('selected').textContent=`TEAM ${teamData[selected.team].name} · ${selected.data.name} #${selected.id+1} · HP ${Math.ceil(selected.hp)} / ${selected.maxHp}${selected.data.immune?'（無敵）':''}${selected.hp<=0?' · 撃破':''}`;
 let p=battle.projectiles.find(p=>p.kind==='dumbbell'),label=$('dumbbellLabel');label.hidden=!p;if(p){let r=canvas.getBoundingClientRect(),q=camera.project(p.sx+(p.tx-p.sx)*p.time/p.duration,18*(1-p.time/p.duration)+1+battle.terrain.heightAt(p.tx,p.tz),p.sz+(p.tz-p.sz)*p.time/p.duration,r.width,r.height);if(q){label.style.left=q[0]+'px';label.style.top=q[1]+'px';}else label.hidden=true;}
 if(battle.result){showBattleReport();if(godActive)setGodMode(false);$('placeToggle').disabled=true;$('winner').textContent=isChallenge()?(battle.result==='CHALLENGE WIN'?'勝利':'敗北'):battle.result;$('result').hidden=battle.endingTime<2;if(battle.endingTime<2)$('selected').textContent='決着しました。最後の動きを表示中…';}}
let nextUI=0,frameError=null;function frame(now){try{if(frameError)return;frameTick(now);}catch(error){paused=true;acc=0;frameError=error;console.error(error);$('fieldFeedback').hidden=false;$('fieldFeedback').textContent='処理を中断しました。設定 → ルール → モードを選び直す で復帰できます。';}finally{requestAnimationFrame(frame);}}
function frameTick(now){const wallDt=Math.max(0,(now-last)/1000||0);let dt=Math.min(.1,wallDt);last=now;if(battle&&!$('battle').hidden){if(!editing&&!battle.result)battle.interventions.tick(wallDt);if(renderer.contextLost){paused=true;$('selected').textContent='3D描画が中断しました。ページを再読込してください。';}if(!editing&&battle.result){battle.step(dt);}else if(!editing&&!paused&&!battle.result){acc+=dt*Number($('speed').value);let steps=0,start=performance.now();while(acc>=1/30&&steps<6&&!battle.result){battle.step(1/30);acc-=1/30;steps++;}simulationMs=performance.now()-start;if(steps)stepMs=simulationMs/steps;}if(!editing)cameraRig.update(dt);let drawStart=performance.now();renderer.draw(battle,camera,selected,marker,editing?unitSelection.ids:null);renderMs=performance.now()-drawStart;if(editing){updateSelectionUI();}if(battle.result||now>=nextUI){ui();syncDock();nextUI=now+(battle.count>700?200:100);}statusTime+=dt;frameCount++;if(statusTime>=1){$('performance').textContent=`${battle.count.toLocaleString()} 人編成 · ${Math.round(frameCount/statusTime)} FPS · ${battle.count>1800?'簡略モデル': '3D'}`;$('perfDetail').textContent=`計算 ${stepMs.toFixed(2)} ms / 更新 · 描画準備 ${renderMs.toFixed(2)} ms / フレーム · Draw Call ${renderer.drawCalls} · 描画パーツ ${renderer.parts.toLocaleString()}`;frameCount=0;statusTime=0;}}}requestAnimationFrame(frame);
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});

let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false;});$('install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();const choice=await installPrompt.userChoice;$('install').hidden=true;installPrompt=null;};window.addEventListener('appinstalled',()=>{$('install').hidden=true;installPrompt=null;});

function updateTeamPresetList(selectedId=null){let warning='';try{teamChoices=[...(isChallenge()?currentMode.definition.teamPresets:[]),...teamPresets,...userTeams()];}catch(e){teamChoices=[...teamPresets];warning=e.message;}
 for(const t of teamIds){const select=$('teamPreset'+t),old=selectedId||select.value;select.replaceChildren(...teamChoices.map(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.name+'（'+teamPresetTotal(p)+'体）'+(isChallenge()?` · ${presetCost(p)}${presetLocked(p)?' 🔒':''}`:'');o.disabled=presetLocked(p);return o;}));select.value=teamChoices.some(p=>p.id===old&&!presetLocked(p))?old:teamChoices.find(p=>!presetLocked(p))?.id||teamChoices[0].id;updateTeamPresetSummary(t);}
 if(warning)$('teamSaveStatus').textContent=warning;
}
function updateTeamPresetSummary(t){const p=teamChoices.find(p=>p.id===$('teamPreset'+t).value)||teamChoices[0];$('teamPresetSummary'+t).textContent=p.description+' / '+teamPresetSummary(p)+(isChallenge()?` / 必要コスト ${presetCost(p)}${presetLocked(p)?' · 使用できません':''}`:'');$('applyTeam'+t).disabled=isChallenge()&&(t!==0||presetLocked(p));}
function updateCameraStatus(){$('followSelected').disabled=editing||!selected?.data||selected.hp<=0;$('freeCamera').hidden=cameraRig.mode!=='follow';$('cameraStatus').textContent=cameraRig.mode==='follow'?`追従：${teamLabel(cameraRig.subject.team)} / ${cameraRig.subject.data.name} #${cameraRig.subject.id+1}`:cameraRig.message;}
function showBattleReport(){if(reportedBattle===battle||!battle.report)return;reportedBattle=battle;const report=battle.report;$('challengeResult').hidden=!isChallenge();if(isChallenge()){const f=challengeFeedback(battle);$('challengeOutcome').textContent=f.won?(currentMode.definition.kind==='defense'?'旗を守りきりました！':'敵陣を突破しました！'):'編成を見直して再挑戦';$('challengeDetails').textContent=currentMode.definition.kind==='defense'?`拠点HP ${Math.ceil(f.baseHp)} / ${f.baseMaxHp} · 防衛時間 ${Math.min(f.duration,Math.floor(f.elapsed+1e-6))}秒 / ${f.duration}秒 · Wave ${f.wave} / ${f.waves} · 自軍撃破数 ${f.playerKills}体`:`敵残存 ${f.enemyRemaining}体 / ギガント残りHP ${f.giantPercent}% / 自軍撃破数 ${f.playerKills}体`;}
 $('reportTime').textContent=`戦闘時間 ${report.time.toFixed(1)}秒`;
 $('reportTeams').replaceChildren(...report.teams.map(t=>{const tr=document.createElement('tr');for(const value of [teamLabel(t.team),t.survivors,t.kills,Math.round(t.damage).toLocaleString(),`${t.spawned}（増援${t.reinforcements}）`]){const td=document.createElement('td');td.textContent=value;tr.append(td);}return tr;}));
 const divine=report.interventions;$('reportGod').textContent=divine?`衝撃 ${divine.uses.shock}回 / 回復 ${divine.uses.heal}回 / 落雷 ${divine.uses.lightning}回 / 増援 ${divine.reinforced}体（${divine.uses.reinforcement}回） / 神による撃破 ${divine.kills}体 / 回復量 ${Math.round(divine.healing).toLocaleString()}`:'介入なし';$('interventionReport').open=false;
 const person=r=>r?`${teamLabel(r.team)} / ${characterData[r.type].name} #${r.id+1}${r.alive?'':'（撃破されたキャラ）'}`:'該当なし';$('reportMvp').textContent=`MVP：${person(report.mvp)}${report.mvp?' · '+report.mvp.kills+'撃破':''}`;$('reportDamage').textContent=`最多ダメージ：${person(report.damageLeader)}${report.damageLeader?' · '+Math.round(report.damageLeader.damage).toLocaleString():''}`;
}
updateTeamPresetList();for(const t of teamIds){$('teamPreset'+t).onchange=()=>updateTeamPresetSummary(t);$('applyTeam'+t).onclick=()=>{const p=teamChoices.find(p=>p.id===$('teamPreset'+t).value);if(isChallenge()&&(t!==0||presetLocked(p))){editorStatus('このプリセットは使用できません。必要コストと使用可能キャラを確認してください。');return;}if(editor.stage.units.some(u=>u.team===t)&&!confirm(`現在のTEAM ${teamData[t].name}を「${p.name}」に置き換えますか？`))return;editAction(()=>{const result=editor.applyTeamPreset(t,p);editSelected=null;queueMicrotask(()=>editorStatus(`TEAM ${teamData[t].name}を${p.name}（${result.units.length}体）を配備しました。${result.adjusted?'障害物などを避けて配置を調整しました。':''}「元に戻す」で編成を戻せます。`));});};}
$('saveTeamPreset').onclick=()=>{try{const t=Number($('saveTeamTarget').value),p=saveTeam($('teamPresetName').value,editor.snapshot(),t);updateTeamPresetList(p.id);$('teamSaveStatus').textContent=`TEAM ${teamData[t].name}の配置を「${p.name}」として保存しました。TEAMカードから呼び出せます。`;}catch(e){$('teamSaveStatus').textContent=e.message;}};
