$('mapButtons').replaceChildren(...mapPresets.map(p=>{const button=document.createElement('button');button.textContent=p.name;button.title=p.description;button.dataset.map=p.id;button.onclick=()=>{try{const result=editor.applyMap(p.id);editSelected=null;refreshEditor();$('mapHint').textContent=p.description;$('mapChooser').open=false;editorStatus(`${p.name}に変更しました。${result.moved?result.moved+'体の位置を調整しました。':''} 軍団と倍率は保持。「元に戻す」で戻せます。`);}catch(e){editorStatus(e.message);}};return button;}));
