$('armyRows').innerHTML=characterData.map((c,t)=>`<label>${c.name}<input id="armyN${t}" type="number" min="0" max="300" step="1" value="0" inputmode="numeric" aria-label="自作軍団 ${c.name}の人数"></label>`).join('');
function armyDraftCounts(){return characterData.map((_,t)=>Number($('armyN'+t).value));}
function updateCustomTotal(){$('customTotal').textContent=`合計 ${armyDraftCounts().reduce((s,n)=>s+(Number.isFinite(n)?n:0),0)}体`+(isChallenge()?` · 必要コスト ${armyDraftCounts().reduce((s,n,t)=>s+(Number.isFinite(n)?n:0)*characterData[t].cost,0)}`:'');}for(const t of characterData.keys())$('armyN'+t).oninput=updateCustomTotal;
function fillArmyDraft(counts){counts.forEach((n,t)=>$('armyN'+t).value=n);updateCustomTotal();}
