 try{editor.rules.assertMultipliersEditing();const values=teamIds.map(t=>Object.fromEntries(['hp','attack','speed'].map(k=>[k,Number($(`mult${t}_${k}`).value)])));const next=normalizeMultipliers(values);editor.checkpoint();editor.stage.multipliers=next;refreshEditor();editorStatus('陣営倍率を更新しました。戦闘開始時に反映されます。');}catch(e){syncMultipliers();editorStatus(e.message);}
